function wireManagement(root,state,h={}){
 if(!root)return;ensure(state);const save=h.save||(()=>{}),rerender=h.rerender||(()=>{}),log=h.log||(()=>{}),toast=h.toast||(()=>{});window.MDXLifecycleStrategy?.wire?.(root,state,{save,rerender,log,toast});window.MDXVariants?.wire?.(root,state,{save,rerender,logEvent:log,toast});window.MDXPrototypeLab?.wire?.(root,state,{save,rerender,log,toast});window.MDXPartsCarryover?.wire?.(root,state,{save,rerender,log,toast});window.MDXGenerationRelease?.wire?.(root,state,{save,rerender,log,toast});window.MDXVehicleVisualStudio?.watch?.(root,state,{save,rerender,log,toast});
 root.querySelector("[data-product-start-new]")?.addEventListener("click",()=>window.dispatchEvent(new CustomEvent("mdx:new-product-line")));
 root.querySelector("[data-platform-start-new]")?.addEventListener("click",()=>window.dispatchEvent(new CustomEvent("mdx:new-platform")));
 root.querySelector("[data-concept-jump]")?.addEventListener("click",()=>root.querySelector("#conceptProgramName")?.scrollIntoView?.({behavior:"smooth",block:"center"}));
 root.querySelectorAll("[data-trim-mix]").forEach(el=>el.addEventListener("change",()=>{const [vid,tid]=el.dataset.trimMix.split(":");if(setTrimMix(state,vid,tid,Number(el.value))){save();rerender();}}));
 root.querySelectorAll("[data-package-rate]").forEach(el=>el.addEventListener("change",()=>{const [vid,pid]=el.dataset.packageRate.split(":");if(setPackageTakeRate(state,vid,pid,Number(el.value))){save();rerender();}}));
 root.querySelectorAll("[data-trim-config]").forEach(el=>el.addEventListener("change",()=>{const [vid,tid]=el.dataset.trimConfig.split(":");if(setTrimConfig(state,vid,tid,el.dataset.field,el.value)){save();rerender();}}));
 root.querySelectorAll("[data-package-add]").forEach(b=>b.addEventListener("click",()=>{const vid=b.dataset.packageAdd,name=root.querySelector("[data-package-name='"+vid+"']")?.value,kind=root.querySelector("[data-package-kind='"+vid+"']")?.value,p=addPackage(state,vid,{name,kind});if(!p){toast("Package could not be added.");return;}save();rerender();}));
 root.querySelectorAll("[data-facelift-scope]").forEach(b=>b.addEventListener("click",()=>{const [vid,scope]=b.dataset.faceliftScope.split(":"),v=state.vehicles.find(x=>x.id===vid);if(!v)return;setFaceliftScope(state,vid,scope,!v.faceliftDraft[scope]);save();rerender();}));
 root.querySelectorAll("[data-product-auto]").forEach(el=>el.addEventListener("change",()=>{const field=el.dataset.field,raw=el.value,patch={};patch[field]=["generationYears","faceliftYears"].includes(field)?Number(raw):raw==="1";if(setProductAutomation(state,el.dataset.productAuto,patch)){save();rerender();}}));
 root.querySelectorAll("[data-model-rename-save]").forEach(b=>b.addEventListener("click",()=>{const id=b.dataset.modelRenameSave,input=root.querySelector("[data-model-rename='"+id+"']"),v=state.vehicles.find(x=>x.id===id),old=v?.name||"";if(!renameVehicle(state,id,input?.value||"")){if(input)input.value=old;toast("Enter a vehicle name first.");return;}log("Renamed "+old+" to "+state.vehicles.find(x=>x.id===id).name+". Product history was preserved.");save();rerender();}));
 root.querySelectorAll("[data-model-rename]").forEach(input=>input.addEventListener("keydown",e=>{if(e.key==="Enter"){e.preventDefault();root.querySelector("[data-model-rename-save='"+input.dataset.modelRename+"']")?.click();}}));
 root.querySelectorAll("[data-model-discontinue]").forEach(b=>b.addEventListener("click",()=>{const v=state.vehicles.find(x=>x.id===b.dataset.modelDiscontinue);if(!v)return;if(!confirm("Discontinue "+v.name+"? Production and automatic updates will stop, but sales and heritage history stay in the company archive."))return;if(!discontinueVehicle(state,v.id)){toast("Vehicle could not be discontinued.");return;}log(v.name+" was discontinued; production stopped and heritage history was preserved.");save();rerender();}));
 root.querySelectorAll("[data-lifecycle-preview]").forEach(canvas=>{const v=state.vehicles.find(x=>x.id===canvas.dataset.lifecyclePreview);if(v)window.MDXProductVisualizer?.renderVehiclePreview?.(canvas,v);});
 root.querySelector("#startConceptProgram")?.addEventListener("click",()=>{const c=startConcept(state,{name:root.querySelector("#conceptProgramName")?.value,segment:root.querySelector("#conceptProgramSegment")?.value,theme:root.querySelector("#conceptProgramTheme")?.value},log);if(!c){toast("Concept program could not be funded.");return;}save();rerender();});
 root.querySelectorAll("[data-concept-toggle]").forEach(b=>b.addEventListener("click",()=>{const c=state.conceptPrograms.find(x=>x.id===b.dataset.conceptToggle);if(!c)return;c.userPaused=!c.userPaused;save();rerender();}));
 root.querySelectorAll("[data-concept-cancel]").forEach(b=>b.addEventListener("click",()=>{if(!confirm("Cancel this concept? Money already spent remains sunk."))return;const r=cancelConcept(state,b.dataset.conceptCancel,log);if(!r){toast("Concept could not be cancelled.");return;}save();rerender();}));
 root.querySelectorAll("[data-concept-develop]").forEach(b=>b.addEventListener("click",()=>{const p=developConcept(state,b.dataset.conceptDevelop,log);if(!p){toast("Production business case could not be created.");return;}save();rerender();toast("Production business case created");}));
 root.querySelectorAll("[data-program-revive]").forEach(b=>b.addEventListener("click",()=>{const raw=b.dataset.programRevive,cut=raw.indexOf(":");if(cut<1)return;const r=reviveCancelledProgram(state,raw.slice(0,cut),raw.slice(cut+1),log);if(!r){toast("Program could not be revived.");return;}save();rerender();}));
}
function runSelfTests(){
 const failures=[],check=(v,m)=>{if(!v)failures.push(m);},s={company:"Lifecycle Motors",campaignId:"lifecycle-test",year:1985,month:0,day:1,cash:50000000,rep:62,vehicles:[{id:"v1",name:"Falcon",createdYear:1984,modelYear:1984,generation:1,productionStatus:"production",active:true,engineId:"e1",transmissionId:"t1",msrp:18000,lifetimeSales:12000,lastMonthSales:900,customerSatisfaction:76,stats:{className:"Mainstream",unitCost:10000,manufacturingUnitCost:10000,reliability:78,quality:75,safety:70,handling:68,comfort:72,mpg:28,hp:140}}],vehiclePrograms:[],enginePrograms:[],transmissionPrograms:[],platformPrograms:[],modelActions:[],engineActions:[],testingSystem:{activeTests:[]},qualitySystem:{recalls:[]},motorsport:{trophies:0},industry:[],engines:[{id:"e1",name:"Base I4",stats:{cost:1200,hp:140}},{id:"e2",name:"Sport V6",stats:{cost:2200,hp:230}}],transmissions:[{id:"t1",name:"Base Manual",stats:{cost:700}},{id:"t2",name:"Sport Auto",stats:{cost:1300}}]};
 ensure(s);const v=s.vehicles[0],econ=vehicleEconomics(v);check(v.trims.length>=3&&Math.round(v.trims.reduce((a,t)=>a+t.targetMix,0))===100,"trim architecture missing or mix invalid");check(v.optionPackages.length>=2&&econ.blendedMsrp>v.msrp&&econ.blendedUnitCost>v.stats.unitCost,"package economics did not reach blended vehicle economics");const trim=v.trims[0];setTrimConfig(s,v.id,trim.id,"engineId","e2");check(trim.engineId==="e2"&&trim.configCostPct>0,"trim-specific powertrain configuration did not change real economics");const addedPackage=addPackage(s,v.id,{name:"Winter Pro",kind:"winter",takeRate:27});check(addedPackage&&addedPackage.takeRate===27,"custom package builder failed");v.lifecycle.freshness=70;v.faceliftDraft={exterior:true,interior:false,technology:false,powertrain:false};const fakeAction={scope:{...v.faceliftDraft}};const freshBefore=v.lifecycle.freshness;onModelActionComplete(s,v,"facelift",fakeAction);check(v.lifecycle.freshness>freshBefore&&v.faceliftDraft.interior===false,"selective facelift scope failed");const first=settleMonth(s,()=>{});check(first.trimUnits===900&&Object.values(v.lastMonthTrimSales).reduce((a,b)=>a+b,0)===900,"actual trim sales did not reconcile to model sales");check(s.nameplates.length===1&&s.nameplates[0].cumulativeSales>=v.lifetimeSales,"nameplate history missing cumulative sales");check(v.reputationMemory.history.length===1&&Number.isFinite(v.reputationMemory.composite),"vehicle reputation memory invalid");const concept=startConcept(s,{name:"Future One",segment:"Sport",theme:"performance"},()=>{});check(!!concept&&concept.status==="active","concept program did not start");for(let i=0;i<concept.totalDays;i++)processDay(s,()=>{});check(concept.status==="complete"&&concept.feedback?.overall>0&&concept.spent>0,"concept did not spend real cash and complete");const cancelled={id:"cancel1",name:"Revive Me",status:"cancelled",budget:1000000,spent:300000,totalDays:100,daysRemaining:50,cancelledPeriod:period(s)-8};s.vehiclePrograms.push(cancelled);const revived=reviveCancelledProgram(s,"vehicle","cancel1",()=>{});check(revived&&cancelled.status==="active"&&cancelled.spent===300000&&cancelled.budget>1000000,"revival failed to preserve sunk spend / add revalidation");const marketState={...s,year:1985,industry:[{status:"active",aiCars:[{active:true,segment:"Mainstream",price:20500,lastSales:800},{active:true,segment:"Mainstream",price:21500,lastSales:600},{active:true,segment:"Luxury",price:50000,lastSales:100}]}]},bench=marketAveragePrice(marketState,"Mainstream",18000);check(bench.count===2&&bench.average>20000&&bench.average<22000,"market average did not use live same-segment rival prices");const beforePrice=v.msrp;onModelActionComplete(marketState,v,"modelyear",{});check(v.msrp!==beforePrice&&v.avgRivalPrice===bench.average,"model-year lifecycle update left MSRP static or lost market benchmark");const activeAction={id:"active_refresh",vehicleId:v.id,status:"active"};marketState.modelActions=[activeAction];v.productAutomation.enabled=true;check(discontinueVehicle(marketState,v.id)&&v.productionStatus==="retired"&&activeAction.status==="cancelled"&&!v.productAutomation.enabled,"discontinue did not stop production, automation, and active lifecycle work together");return{ok:failures.length===0,failures};
}
window.MDXProductLifecycle={restartVehicle,advanceRelaunches,ensure,ensureVehicle,vehicleEconomics,lifecycleDemandMultiplier,demandMultiplier:lifecycleDemandMultiplier,marketAveragePrice,applyLifecyclePricing,settleMonth,processDay,onModelActionStarted,onModelActionComplete,startConcept,cancelConcept,developConcept,reviveCancelledProgram,setTrimMix,setPackageTakeRate,setTrimConfig,addPackage,setFaceliftScope,renameVehicle,discontinueVehicle,setProductAutomation,scheduleProductAutomation,vehicleJourney,vehicleJourneyMarkup,generationLineageMarkup,renderManagement,wireManagement,summaryMarkup,runSelfTests,TRIM_ARCHETYPES,PACKAGE_ARCHETYPES,INTERIOR_LEVELS,SUSPENSION_LEVELS};
